package com.cowave.search.notice

import org.slf4j.LoggerFactory
import org.springframework.scheduling.annotation.Async
import org.springframework.stereotype.Service
import org.springframework.web.client.RestClient

/**
 * Telegram Bot API를 통한 알림 서비스.
 *
 * - WebFlux 없이 spring-web의 RestClient 사용
 * - @Async로 비동기 처리 (색인 완료/실패 알림이 주 흐름을 블로킹하지 않도록)
 * - enabled=false 이면 전송 생략
 */
@Service
class TelegramNoticeService(
    private val restClientBuilder: RestClient.Builder,
    private val properties: TelegramProperties,
) {
    private val logger = LoggerFactory.getLogger(TelegramNoticeService::class.java)

    private val restClient: RestClient by lazy { restClientBuilder.build() }

    @Async
    fun sendMessage(text: String) {
        if (!properties.enabled) return
        if (properties.bot.isBlank() || properties.chat.isBlank()) {
            logger.warn("Telegram 설정이 올바르지 않습니다 (bot/chat 미설정)")
            return
        }

        runCatching {
            restClient
                .post()
                .uri("https://api.telegram.org/bot${properties.bot}/sendMessage")
                .body(mapOf("chat_id" to properties.chat, "text" to text))
                .retrieve()
                .toBodilessEntity()
        }.onFailure { e ->
            logger.warn("Telegram 알림 발송 실패: ${e.message}")
        }
    }
}

package com.cowave.search.notice

import org.springframework.boot.context.properties.ConfigurationProperties

@ConfigurationProperties(prefix = "dsearch.notice.telegram")
class TelegramProperties {
    var enabled: Boolean = false
    var bot: String = ""
    var chat: String = ""
}

package com.cowave.search.jdbc.model

import org.bson.types.ObjectId
import org.springframework.data.annotation.Id
import org.springframework.data.mongodb.core.index.Indexed
import org.springframework.data.mongodb.core.mapping.Document

/**
 * JDBC 연결 설정 도큐먼트.
 *
 * 기존 ES `.dsearch_jdbc` 도큐먼트를 MongoDB로 이전.
 * - clusterId: 어느 클러스터에 속하는지 구분
 */
@Document(collection = "jdbc_info")
data class JdbcInfo(
    @Id
    val id: String = ObjectId.get().toHexString(),
    @Indexed
    val clusterId: String,
    var name: String,
    var provider: String,
    var driver: String,
    var address: String,
    var port: String,
    var dbName: String,
    var user: String? = null,
    var password: String? = null,
    var url: String? = null,
    var params: String? = null,
)

package com.cowave.search.collection.service

import org.slf4j.LoggerFactory
import org.springframework.scheduling.TaskScheduler
import org.springframework.scheduling.support.CronTrigger
import org.springframework.stereotype.Component
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.ScheduledFuture

/**
 * 컬렉션 크론 스케줄 관리.
 *
 * - 키: "{clusterId}-{collectionId}-{cron}"
 * - 복수 크론: "||" 구분자로 여러 스케줄 등록 가능
 * - 5자리 cron → Spring 6자리 cron 변환 ("0 " + cron)
 */
@Component
class IndexingScheduler(
    private val taskScheduler: TaskScheduler,
) {
    private val logger = LoggerFactory.getLogger(IndexingScheduler::class.java)
    private val schedules = ConcurrentHashMap<String, ScheduledFuture<*>>()

    fun register(
        clusterId: String,
        collectionId: String,
        cron: String,
        action: () -> Unit,
    ) {
        val cronExpressions = cron.split("||").map { it.trim() }.filter { it.isNotBlank() }
        cronExpressions.forEach { cronExpr ->
            val key = scheduleKey(clusterId, collectionId, cronExpr)
            if (schedules.containsKey(key)) {
                logger.debug("스케줄 이미 등록됨: {}", key)
                return@forEach
            }
            runCatching {
                val springCron = toSpringCron(cronExpr)
                val future =
                    taskScheduler.schedule(
                        { action() },
                        CronTrigger(springCron),
                    )
                schedules[key] = future!!
                logger.info("스케줄 등록: {} ({})", key, springCron)
            }.onFailure { e ->
                logger.error("스케줄 등록 실패 [{}]: {}", key, e.message)
            }
        }
    }

    fun unregister(
        clusterId: String,
        collectionId: String,
    ) {
        val prefix = "$clusterId-$collectionId-"
        schedules.keys
            .filter { it.startsWith(prefix) }
            .forEach { key ->
                schedules.remove(key)?.cancel(false)
                logger.info("스케줄 해제: {}", key)
            }
    }

    fun registeredKeys(): Set<String> = schedules.keys.toSet()

    private fun scheduleKey(
        clusterId: String,
        collectionId: String,
        cron: String,
    ) = "$clusterId-$collectionId-$cron"

    /**
     * 5자리 표준 cron → Spring 6자리 cron.
     * 이미 6자리인 경우 그대로 반환.
     */
    private fun toSpringCron(cron: String): String {
        val parts = cron.trim().split("\\s+".toRegex())
        return if (parts.size == 5) "0 $cron" else cron
    }
}

package com.cowave.search.config

import org.springframework.context.annotation.Bean
import org.springframework.context.annotation.Configuration
import org.springframework.scheduling.TaskScheduler
import org.springframework.scheduling.concurrent.ThreadPoolTaskScheduler

@Configuration
class SchedulerConfig {
    @Bean
    fun taskScheduler(): TaskScheduler {
        val scheduler = ThreadPoolTaskScheduler()
        scheduler.setPoolSize(4)
        scheduler.setThreadNamePrefix("dsearch-scheduler-")
        scheduler.setWaitForTasksToCompleteOnShutdown(true)
        scheduler.setAwaitTerminationSeconds(30)
        scheduler.initialize()
        return scheduler
    }
}

