## 2. DataSourceAdapter 인터페이스 설계 (3-9)

### 2-1. DataSourceAdapter 인터페이스 정의

```kotlin
package com.cowave.search.datasource

/**
 * 데이터 소스 공통 인터페이스.
 * JDBC, MongoDB, Kafka, Iceberg 등 다양한 소스를 플러그인 방식으로 지원.
 */
interface DataSourceAdapter : AutoCloseable {

    /** 데이터 소스 연결 */
    fun connect(config: DataSourceConfig)

    /** 연결 테스트 (빠른 응답, 타임아웃 짧게) */
    fun testConnection(config: DataSourceConfig): ConnectionTestResult

    /**
     * 배치 단위 데이터 조회.
     * @param query 데이터 조회 조건 (SQL, MongoDB filter JSON 등)
     * @param batchSize 배치 크기
     * @param cursor 이전 배치의 마지막 커서 (null이면 처음부터)
     * @return DataBatch (데이터 + 다음 커서)
     */
    fun fetchBatch(query: String, batchSize: Int, cursor: Any? = null): DataBatch

    /** 전체 건수 추정 (진행률 표시용, 정확하지 않아도 됨) */
    fun estimateTotal(query: String): Long

    /** 지원하는 데이터 소스 타입 */
    fun type(): DataSourceType
}

data class DataSourceConfig(
    val type: DataSourceType,
    val properties: Map<String, String>,  // 타입별 설정값
)

data class ConnectionTestResult(
    val success: Boolean,
    val message: String? = null,
    val latencyMs: Long? = null,
)

data class DataBatch(
    val rows: List<Map<String, Any?>>,
    val cursor: Any? = null,   // 다음 배치 시작 커서
    val hasMore: Boolean,
    val fetchedCount: Int,
)

enum class DataSourceType {
    JDBC,       // MySQL, Oracle, PostgreSQL, MariaDB, Altibase
    HIVE,       // Hue → Hive/Impala (JDBC 재사용)
    MONGODB,    // Phase 4
    KAFKA,      // Phase 4
    ICEBERG,    // Phase 4+
}
```

### 2-2. JdbcDataSourceAdapter 구현 방안

```kotlin
@Component
class JdbcDataSourceAdapter : DataSourceAdapter {
    private var connection: java.sql.Connection? = null

    override fun connect(config: DataSourceConfig) {
        val driver = config.properties["driver"]!!
        val url = config.properties["url"]!!
        val user = config.properties["user"]
        val password = config.properties["password"]

        Class.forName(driver)
        connection = DriverManager.getConnection(url, user, password)
    }

    override fun testConnection(config: DataSourceConfig): ConnectionTestResult {
        val start = System.currentTimeMillis()
        return runCatching {
            connect(config)
            connection?.isValid(5) ?: false
        }.fold(
            onSuccess = { valid ->
                ConnectionTestResult(
                    success = valid,
                    message = if (valid) "연결 성공" else "연결 검증 실패",
                    latencyMs = System.currentTimeMillis() - start,
                )
            },
            onFailure = { e ->
                ConnectionTestResult(success = false, message = e.message)
            },
        ).also { close() }
    }

    override fun fetchBatch(query: String, batchSize: Int, cursor: Any?): DataBatch {
        val conn = connection ?: throw IllegalStateException("연결되지 않음")
        val stmt = conn.createStatement()
        stmt.fetchSize = batchSize

        // cursor 기반 페이징: LIMIT/OFFSET 또는 커서 조건 (소스 DB에 따라)
        val offset = (cursor as? Long) ?: 0L
        val pagedQuery = "$query LIMIT $batchSize OFFSET $offset"

        val rs = stmt.executeQuery(pagedQuery)
        val meta = rs.metaData
        val rows = mutableListOf<Map<String, Any?>>()
        while (rs.next()) {
            val row = (1..meta.columnCount).associate { i ->
                meta.getColumnLabel(i) to rs.getObject(i)
            }
            rows.add(row)
        }
        rs.close()
        stmt.close()

        return DataBatch(
            rows = rows,
            cursor = offset + rows.size,
            hasMore = rows.size == batchSize,
            fetchedCount = rows.size,
        )
    }

    override fun estimateTotal(query: String): Long {
        val conn = connection ?: return 0
        val countQuery = "SELECT COUNT(*) FROM ($query) t"
        val rs = conn.createStatement().executeQuery(countQuery)
        return if (rs.next()) rs.getLong(1) else 0
    }

    override fun type(): DataSourceType = DataSourceType.JDBC

    override fun close() {
        runCatching { connection?.close() }
        connection = null
    }
}
```

**기존 JdbcInfo 모델과 통합**:
```kotlin
// JdbcInfo → DataSourceConfig 변환
fun JdbcInfo.toDataSourceConfig(): DataSourceConfig = DataSourceConfig(
    type = DataSourceType.JDBC,
    properties = mapOf(
        "driver" to driver,
        "url" to (url ?: buildJdbcUrl()),
        "user" to (user ?: ""),
        "password" to (password ?: ""),
    ),
)

private fun JdbcInfo.buildJdbcUrl(): String =
    when (provider.lowercase()) {
        "mysql" -> "jdbc:mysql://$address:$port/$dbName${params?.let { "?$it" } ?: ""}"
        "oracle" -> "jdbc:oracle:thin:@$address:$port:$dbName"
        "postgresql" -> "jdbc:postgresql://$address:$port/$dbName"
        else -> "jdbc:$provider://$address:$port/$dbName"
    }
```

### 2-3. Hue/Hive/Impala 확장 (JDBC 재사용)

**핵심**: Hue는 데이터 소스가 아닌 SQL 인터페이스. 실제로는 Hive/Impala JDBC Driver를 사용.

| 항목 | Hive | Impala |
|------|------|--------|
| JDBC Driver | `org.apache.hive.jdbc.HiveDriver` | `com.cloudera.impala.jdbc.Driver` |
| URL 패턴 | `jdbc:hive2://{host}:{port}/{db}` | `jdbc:impala://{host}:{port}/{db}` |
| 기본 포트 | 10000 | 21050 |
| 의존성 | `org.apache.hive:hive-jdbc:4.x` | `com.cloudera.impala:impala-jdbc:2.x` |
| 인증 | Kerberos / LDAP / NOSASL | Kerberos / LDAP |

**구현 방법**: JdbcDataSourceAdapter를 그대로 재사용. `provider`를 `hive` 또는 `impala`로 설정하고, 해당 JDBC URL 패턴만 `buildJdbcUrl()`에 추가.

```kotlin
// buildJdbcUrl()에 추가
"hive" -> "jdbc:hive2://$address:$port/$dbName"
"impala" -> "jdbc:impala://$address:$port/$dbName"
```

**Phase 3에서의 실제 작업**:
1. `build.gradle.kts`에 Hive/Impala JDBC 드라이버 의존성 추가 (runtimeOnly)
2. `buildJdbcUrl()`에 hive/impala 패턴 추가
3. 연결 테스트에서 Hive/Impala JDBC 검증

### 2-4. DataSourceInfo 모델 (JdbcInfo 일반화 마이그레이션)

```kotlin
@Document(collection = "data_sources")
@CompoundIndex(def = "{'clusterId': 1, 'name': 1}", unique = true)
data class DataSourceInfo(
    @Id val id: String = ObjectId.get().toHexString(),
    @Indexed val clusterId: String,
    val name: String,
    val type: DataSourceType,

    // == JDBC 공통 (MySQL, Oracle, PostgreSQL, Hive, Impala) ==
    val driver: String? = null,
    val url: String? = null,
    val address: String? = null,
    val port: String? = null,
    val dbName: String? = null,
    val username: String? = null,
    val password: String? = null,
    val params: String? = null,
    val provider: String? = null,   // mysql, oracle, hive, impala 등

    // == MongoDB 전용 (Phase 4) ==
    val connectionString: String? = null,
    val database: String? = null,
    val collection: String? = null,

    // == Kafka 전용 (Phase 4) ==
    val bootstrapServers: String? = null,
    val topic: String? = null,
    val groupId: String? = null,
    val schemaRegistryUrl: String? = null,

    // == Iceberg 전용 (Phase 4+) ==
    val catalogType: String? = null,
    val catalogUri: String? = null,
    val warehouse: String? = null,
    val tableName: String? = null,

    val createdAt: Instant = Instant.now(),
    val updatedAt: Instant = Instant.now(),
)
```

**마이그레이션 전략 (JdbcInfo → DataSourceInfo)**:

| 단계 | 작업 | Phase |
|------|------|-------|
| 1 | `DataSourceInfo` 모델 + `DataSourceRepository` 생성 | Phase 3 |
| 2 | `JdbcInfo` → `DataSourceInfo` 데이터 마이그레이션 스크립트 | Phase 3 |
| 3 | `Collection.jdbcId` → `Collection.dataSourceId` 참조 변경 | Phase 3 |
| 4 | `JdbcInfo` 모델 + `JdbcInfoRepository` deprecated → 삭제 | Phase 3 완료 시 |

**마이그레이션 스크립트**:
```kotlin
@Component
class DataSourceMigration(
    private val jdbcInfoRepository: JdbcInfoRepository,
    private val dataSourceInfoRepository: DataSourceInfoRepository,
) {
    @PostConstruct
    fun migrate() {
        if (dataSourceInfoRepository.count() > 0) return  // 이미 마이그레이션됨

        jdbcInfoRepository.findAll().forEach { jdbc ->
            dataSourceInfoRepository.save(
                DataSourceInfo(
                    id = jdbc.id,  // ID 유지하여 참조 깨지지 않도록
                    clusterId = jdbc.clusterId,
                    name = jdbc.name,
                    type = DataSourceType.JDBC,
                    driver = jdbc.driver,
                    url = jdbc.url,
                    address = jdbc.address,
                    port = jdbc.port,
                    dbName = jdbc.dbName,
                    username = jdbc.user,
                    password = jdbc.password,
                    params = jdbc.params,
                    provider = jdbc.provider,
                ),
            )
        }
    }
}
```

### 2-5. Phase 3 vs Phase 4 범위

| 항목 | Phase 3 | Phase 4 |
|------|---------|---------|
| DataSourceAdapter 인터페이스 | 정의 + JdbcDataSourceAdapter 구현 | MongoDBDataSourceAdapter, KafkaDataSourceAdapter |
| DataSourceInfo 모델 | 생성 + JdbcInfo 마이그레이션 | MongoDB/Kafka/Iceberg 전용 필드 활용 |
| Hive/Impala 확장 | JDBC 드라이버 추가 + URL 패턴 | - |
| DataSourceAdapterFactory | 팩토리 패턴 (JDBC/HIVE만) | MongoDB/Kafka/Iceberg 어댑터 등록 |
| Collection 연동 | `dataSourceId` 참조 전환 | 어댑터 기반 색인 실행 |

**구현 난이도**: 중간 (인터페이스 설계 + JdbcInfo 마이그레이션이 주 작업)
**리스크**: 낮음 (JDBC 재사용이므로 기존 로직 변경 최소)

---

## 3. 집계 쿼리 빌더 Tier 1 설계 (3-10)

### 3-1. Tier 1 지원 집계 유형 (8개)

| # | 카테고리 | 집계 유형 | ES 9.x Java API Client Builder | 대상 필드 타입 |
|---|---------|----------|-------------------------------|-------------|
| 1 | Bucket | `terms` | `a.terms(t -> t.field(f).size(s))` | keyword, integer, long |
| 2 | Bucket | `date_histogram` | `a.dateHistogram(d -> d.field(f).calendarInterval(ci))` | date |
| 3 | Bucket | `histogram` | `a.histogram(h -> h.field(f).interval(i))` | integer, long, float, double |
| 4 | Bucket | `range` | `a.range(r -> r.field(f).ranges(rr -> rr.from("0").to("100")))` | integer, long, float, double |
| 5 | Bucket | `filters` | `a.filters(f -> f.filters(fb -> fb.keyed(map)))` | 모든 타입 (쿼리 기반) |
| 6 | Metric | `avg` / `sum` / `min` / `max` / `count` (value_count) | `a.avg(v -> v.field(f))` | integer, long, float, double |
| 7 | Metric | `cardinality` | `a.cardinality(c -> c.field(f))` | 모든 타입 |
| 8 | Metric | `value_count` | `a.valueCount(v -> v.field(f))` | 모든 타입 |

### 3-2. AggregationDslBuilder 구현 전략

```kotlin
@Component
class AggregationDslBuilder {

    /**
     * AggregationNode 트리 → ES Java API Client Aggregation Map 변환.
     * 재귀적으로 sub-aggregation 처리 (Tier 2에서 활용).
     */
    fun build(nodes: List<AggregationNode>): Map<String, Aggregation> {
        return nodes.associate { node ->
            node.name to buildSingleAggregation(node)
        }
    }

    private fun buildSingleAggregation(node: AggregationNode): Aggregation {
        return Aggregation.of { agg ->
            when (node.type) {
                // === Bucket Aggregations ===
                AggregationType.TERMS -> agg.terms { t ->
                    t.field(node.field)
                        .size(node.params["size"]?.toString()?.toInt() ?: 10)
                }
                AggregationType.DATE_HISTOGRAM -> agg.dateHistogram { d ->
                    d.field(node.field)
                        .calendarInterval(
                            CalendarInterval._DESERIALIZER.parse(
                                node.params["interval"]?.toString() ?: "month"
                            )
                        )
                        .also { builder ->
                            node.params["format"]?.let { fmt ->
                                builder.format(fmt.toString())
                            }
                        }
                }
                AggregationType.HISTOGRAM -> agg.histogram { h ->
                    h.field(node.field)
                        .interval(node.params["interval"]?.toString()?.toDouble() ?: 10.0)
                }
                AggregationType.RANGE -> agg.range { r ->
                    r.field(node.field)
                        .ranges(parseRanges(node.params["ranges"]))
                }
                AggregationType.FILTERS -> agg.filters { f ->
                    // filters는 named query 방식
                    f.filters(buildNamedFilters(node.params["filters"]))
                }

                // === Metric Aggregations ===
                AggregationType.AVG -> agg.avg { v -> v.field(node.field) }
                AggregationType.SUM -> agg.sum { v -> v.field(node.field) }
                AggregationType.MIN -> agg.min { v -> v.field(node.field) }
                AggregationType.MAX -> agg.max { v -> v.field(node.field) }
                AggregationType.VALUE_COUNT -> agg.valueCount { v -> v.field(node.field) }
                AggregationType.CARDINALITY -> agg.cardinality { c -> c.field(node.field) }
            }

            // Sub-aggregations (Tier 2에서 활용, Tier 1에서는 빈 리스트)
            if (node.subAggregations.isNotEmpty()) {
                val subAggs = build(node.subAggregations)
                subAggs.forEach { (name, subAgg) ->
                    agg.aggregations(name, subAgg)
                }
            }
        }
    }

    private fun parseRanges(rangesParam: Any?): List<AggregationRange> {
        // ranges: [{"from": 0, "to": 50}, {"from": 50, "to": 100}, {"from": 100}]
        val ranges = (rangesParam as? List<*>) ?: return emptyList()
        return ranges.filterIsInstance<Map<*, *>>().map { r ->
            AggregationRange.of { ar ->
                r["from"]?.toString()?.let { ar.from(it) }
                r["to"]?.toString()?.let { ar.to(it) }
                r["key"]?.toString()?.let { ar.key(it) }
            }
        }
    }

    private fun buildNamedFilters(filtersParam: Any?): Buckets<Query> {
        // filters: {"active": {"term": {"status": "active"}}, "inactive": ...}
        val filters = (filtersParam as? Map<*, *>) ?: return Buckets.of { it.keyed(emptyMap()) }
        val queryMap = filters.entries.associate { (key, value) ->
            key.toString() to Query.of { q ->
                q.withJson(StringReader(objectMapper.writeValueAsString(value)))
            }
        }
        return Buckets.of { it.keyed(queryMap) }
    }
}

enum class AggregationType {
    // Bucket
    TERMS, DATE_HISTOGRAM, HISTOGRAM, RANGE, FILTERS,
    // Metric
    AVG, SUM, MIN, MAX, VALUE_COUNT, CARDINALITY,
}

data class AggregationNode(
    val name: String,
    val type: AggregationType,
    val field: String,
    val params: Map<String, Any> = emptyMap(),
    val subAggregations: List<AggregationNode> = emptyList(),  // Tier 2
)
```

### 3-3. ES 9.x Aggregation API 매핑 (상세)

```kotlin
// 실제 ES 호출 (AggregationExecutor)
@Service
class AggregationExecutor(private val clientFactory: ElasticsearchClientFactory) {

    fun execute(
        clusterId: String,
        index: String,
        aggregations: Map<String, Aggregation>,
        query: Map<String, Any>? = null,
    ): SearchResponse<JsonData> {
        val esClient = clientFactory.getClient(clusterId)
        return esClient.search({ s ->
            s.index(index)
                .size(0)  // 집계만 필요
                .aggregations(aggregations)
                .also { builder ->
                    if (query != null) {
                        builder.query { q ->
                            q.withJson(StringReader(objectMapper.writeValueAsString(query)))
                        }
                    }
                }
        }, JsonData::class.java)
    }
}

// 응답 파싱 (AggregationResponseParser)
@Component
class AggregationResponseParser {

    fun parse(response: SearchResponse<JsonData>): Map<String, Any> {
        val result = mutableMapOf<String, Any>()
        response.aggregations().forEach { (name, agg) ->
            result[name] = parseAggregate(agg)
        }
        return result
    }

    private fun parseAggregate(agg: Aggregate): Any {
        return when {
            agg.isSterms() -> parseBuckets(agg.sterms().buckets().array()) { it.key().stringValue() to it.docCount() }
            agg.isLterms() -> parseBuckets(agg.lterms().buckets().array()) { it.key().toString() to it.docCount() }
            agg.isDateHistogram() -> parseBuckets(agg.dateHistogram().buckets().array()) { it.keyAsString() to it.docCount() }
            agg.isHistogram() -> parseBuckets(agg.histogram().buckets().array()) { it.key().toString() to it.docCount() }
            agg.isRange() -> parseBuckets(agg.range().buckets().array()) { (it.key() ?: "${it.from()}-${it.to()}") to it.docCount() }
            agg.isFilters() -> {
                agg.filters().buckets().keyed().mapValues { (_, bucket) -> bucket.docCount() }
            }
            agg.isAvg() -> mapOf("value" to agg.avg().value())
            agg.isSum() -> mapOf("value" to agg.sum().value())
            agg.isMin() -> mapOf("value" to agg.min().value())
            agg.isMax() -> mapOf("value" to agg.max().value())
            agg.isValueCount() -> mapOf("value" to agg.valueCount().value())
            agg.isCardinality() -> mapOf("value" to agg.cardinality().value())
            else -> mapOf("_type" to agg._kind().name)
        }
    }

    private fun <T> parseBuckets(buckets: List<T>, extractor: (T) -> Pair<String, Long>): List<Map<String, Any>> {
        return buckets.map { bucket ->
            val (key, count) = extractor(bucket)
            mapOf("key" to key, "doc_count" to count)
        }
    }
}
