### 3-5. 필드 자동완성 (인덱스 매핑 기반)

```kotlin
@Service
class AggregationFieldService(private val clientFactory: ElasticsearchClientFactory) {

    /**
     * 인덱스 매핑에서 집계 가능한 필드를 추출하고, 
     * 필드 타입에 따라 사용 가능한 집계 유형을 매핑.
     */
    fun getAggregableFields(clusterId: String, index: String): List<AggregableField> {
        val esClient = clientFactory.getClient(clusterId)
        val mappingResponse = esClient.indices().getMapping { it.index(index) }

        return mappingResponse.result().values
            .flatMap { it.mappings().properties().entries }
            .flatMap { (name, prop) -> extractAggregableFields(name, prop) }
    }

    private fun extractAggregableFields(
        name: String,
        property: Property,
    ): List<AggregableField> {
        val esType = property._kind().jsonValue()  // "keyword", "long", "date" 등
        val supportedAggs = FIELD_TYPE_TO_AGGREGATIONS[esType] ?: return emptyList()

        return listOf(
            AggregableField(
                field = name,
                type = esType,
                supportedAggregations = supportedAggs,
            ),
        )
    }

    companion object {
        /**
         * ES 필드 타입 → 지원 가능한 집계 유형 매핑.
         * 프론트엔드 빌더의 필드 선택 드롭다운에 사용.
         */
        val FIELD_TYPE_TO_AGGREGATIONS: Map<String, List<AggregationType>> = mapOf(
            "keyword" to listOf(
                AggregationType.TERMS, AggregationType.CARDINALITY, 
                AggregationType.VALUE_COUNT, AggregationType.FILTERS,
            ),
            "text" to listOf(
                // text 필드는 직접 집계 불가 — .keyword sub-field 안내
            ),
            "long" to NUMERIC_AGGS,
            "integer" to NUMERIC_AGGS,
            "short" to NUMERIC_AGGS,
            "float" to NUMERIC_AGGS,
            "double" to NUMERIC_AGGS,
            "date" to listOf(
                AggregationType.DATE_HISTOGRAM, AggregationType.RANGE,
                AggregationType.CARDINALITY, AggregationType.VALUE_COUNT,
                AggregationType.MIN, AggregationType.MAX,
            ),
            "boolean" to listOf(
                AggregationType.TERMS, AggregationType.CARDINALITY,
                AggregationType.VALUE_COUNT,
            ),
            "ip" to listOf(
                AggregationType.TERMS, AggregationType.CARDINALITY,
                AggregationType.RANGE,
            ),
        )

        private val NUMERIC_AGGS = listOf(
            AggregationType.TERMS, AggregationType.HISTOGRAM, AggregationType.RANGE,
            AggregationType.AVG, AggregationType.SUM, AggregationType.MIN,
            AggregationType.MAX, AggregationType.VALUE_COUNT, AggregationType.CARDINALITY,
        )
    }
}

data class AggregableField(
    val field: String,
    val type: String,
    val supportedAggregations: List<AggregationType>,
)
