// NoticeMessageFormatter (유틸 또는 TelegramNoticeService 내부)
object NoticeMessageFormatter {
    fun indexingTimeout(info: IndexingInfo): String {
        val elapsed = (System.currentTimeMillis() - info.startTime) / 60_000
        return """
            |[TIMEOUT] 색인 타임아웃
            |컬렉션: ${info.collection.name}
            |인덱스: ${info.index}
            |경과 시간: ${elapsed}분
        """.trimMargin()
    }

    fun indexingError(info: IndexingInfo, message: String?): String = """
        |[ERROR] 색인 실패
        |컬렉션: ${info.collection.name}
        |인덱스: ${info.index}
        |오류: ${message ?: "알 수 없음"}
    """.trimMargin()

    fun indexingSuccess(info: IndexingInfo): String {
        val elapsed = ((info.endTime ?: System.currentTimeMillis()) - info.startTime) / 1000
        return """
            |[SUCCESS] 색인 완료
            |컬렉션: ${info.collection.name}
            |인덱스: ${info.index}
            |소요: ${elapsed}초
        """.trimMargin()
    }
}
