### 2-2. JdbcDataSourceAdapter 구현 방안

```kotlin
@Component
class JdbcDataSourceAdapter : DataSourceAdapter {
    private var connection: java.sql.Connection? = null

    override fun connect(config: DataSourceConfig) {
        val driver = config.properties["driver"]!!
        val url = config.properties["url"]!!
        val user = config.properties["user"]
        val password = config.properties["password"]

        Class.forName(driver)
        connection = DriverManager.getConnection(url, user, password)
    }

    override fun testConnection(config: DataSourceConfig): ConnectionTestResult {
        val start = System.currentTimeMillis()
        return runCatching {
            connect(config)
            connection?.isValid(5) ?: false
        }.fold(
            onSuccess = { valid ->
                ConnectionTestResult(
                    success = valid,
                    message = if (valid) "연결 성공" else "연결 검증 실패",
                    latencyMs = System.currentTimeMillis() - start,
                )
            },
            onFailure = { e ->
                ConnectionTestResult(success = false, message = e.message)
            },
        ).also { close() }
    }

    override fun fetchBatch(query: String, batchSize: Int, cursor: Any?): DataBatch {
        val conn = connection ?: throw IllegalStateException("연결되지 않음")
        val stmt = conn.createStatement()
        stmt.fetchSize = batchSize

        // cursor 기반 페이징: LIMIT/OFFSET 또는 커서 조건 (소스 DB에 따라)
        val offset = (cursor as? Long) ?: 0L
        val pagedQuery = "$query LIMIT $batchSize OFFSET $offset"

        val rs = stmt.executeQuery(pagedQuery)
        val meta = rs.metaData
        val rows = mutableListOf<Map<String, Any?>>()
        while (rs.next()) {
            val row = (1..meta.columnCount).associate { i ->
                meta.getColumnLabel(i) to rs.getObject(i)
            }
            rows.add(row)
        }
        rs.close()
        stmt.close()

        return DataBatch(
            rows = rows,
            cursor = offset + rows.size,
            hasMore = rows.size == batchSize,
            fetchedCount = rows.size,
        )
    }

    override fun estimateTotal(query: String): Long {
        val conn = connection ?: return 0
        val countQuery = "SELECT COUNT(*) FROM ($query) t"
        val rs = conn.createStatement().executeQuery(countQuery)
        return if (rs.next()) rs.getLong(1) else 0
    }

    override fun type(): DataSourceType = DataSourceType.JDBC

    override fun close() {
        runCatching { connection?.close() }
        connection = null
    }
}
```

**기존 JdbcInfo 모델과 통합**:
