private fun JdbcInfo.buildJdbcUrl(): String =
    when (provider.lowercase()) {
        "mysql" -> "jdbc:mysql://$address:$port/$dbName${params?.let { "?$it" } ?: ""}"
        "oracle" -> "jdbc:oracle:thin:@$address:$port:$dbName"
        "postgresql" -> "jdbc:postgresql://$address:$port/$dbName"
        else -> "jdbc:$provider://$address:$port/$dbName"
    }
