## 3. 집계 쿼리 빌더 Tier 1 설계 (3-10)

### 3-1. Tier 1 지원 집계 유형 (8개)

| # | 카테고리 | 집계 유형 | ES 9.x Java API Client Builder | 대상 필드 타입 |
|---|---------|----------|-------------------------------|-------------|
| 1 | Bucket | `terms` | `a.terms(t -> t.field(f).size(s))` | keyword, integer, long |
| 2 | Bucket | `date_histogram` | `a.dateHistogram(d -> d.field(f).calendarInterval(ci))` | date |
| 3 | Bucket | `histogram` | `a.histogram(h -> h.field(f).interval(i))` | integer, long, float, double |
| 4 | Bucket | `range` | `a.range(r -> r.field(f).ranges(rr -> rr.from("0").to("100")))` | integer, long, float, double |
| 5 | Bucket | `filters` | `a.filters(f -> f.filters(fb -> fb.keyed(map)))` | 모든 타입 (쿼리 기반) |
| 6 | Metric | `avg` / `sum` / `min` / `max` / `count` (value_count) | `a.avg(v -> v.field(f))` | integer, long, float, double |
| 7 | Metric | `cardinality` | `a.cardinality(c -> c.field(f))` | 모든 타입 |
| 8 | Metric | `value_count` | `a.valueCount(v -> v.field(f))` | 모든 타입 |

### 3-2. AggregationDslBuilder 구현 전략

```kotlin
@Component
class AggregationDslBuilder {

    /**
     * AggregationNode 트리 → ES Java API Client Aggregation Map 변환.
     * 재귀적으로 sub-aggregation 처리 (Tier 2에서 활용).
     */
    fun build(nodes: List<AggregationNode>): Map<String, Aggregation> {
        return nodes.associate { node ->
            node.name to buildSingleAggregation(node)
        }
    }

    private fun buildSingleAggregation(node: AggregationNode): Aggregation {
        return Aggregation.of { agg ->
            when (node.type) {
                // === Bucket Aggregations ===
                AggregationType.TERMS -> agg.terms { t ->
                    t.field(node.field)
                        .size(node.params["size"]?.toString()?.toInt() ?: 10)
                }
                AggregationType.DATE_HISTOGRAM -> agg.dateHistogram { d ->
                    d.field(node.field)
                        .calendarInterval(
                            CalendarInterval._DESERIALIZER.parse(
                                node.params["interval"]?.toString() ?: "month"
                            )
                        )
                        .also { builder ->
                            node.params["format"]?.let { fmt ->
                                builder.format(fmt.toString())
                            }
                        }
                }
                AggregationType.HISTOGRAM -> agg.histogram { h ->
                    h.field(node.field)
                        .interval(node.params["interval"]?.toString()?.toDouble() ?: 10.0)
                }
                AggregationType.RANGE -> agg.range { r ->
                    r.field(node.field)
                        .ranges(parseRanges(node.params["ranges"]))
                }
                AggregationType.FILTERS -> agg.filters { f ->
                    // filters는 named query 방식
                    f.filters(buildNamedFilters(node.params["filters"]))
                }

                // === Metric Aggregations ===
                AggregationType.AVG -> agg.avg { v -> v.field(node.field) }
                AggregationType.SUM -> agg.sum { v -> v.field(node.field) }
                AggregationType.MIN -> agg.min { v -> v.field(node.field) }
                AggregationType.MAX -> agg.max { v -> v.field(node.field) }
                AggregationType.VALUE_COUNT -> agg.valueCount { v -> v.field(node.field) }
                AggregationType.CARDINALITY -> agg.cardinality { c -> c.field(node.field) }
            }

            // Sub-aggregations (Tier 2에서 활용, Tier 1에서는 빈 리스트)
            if (node.subAggregations.isNotEmpty()) {
                val subAggs = build(node.subAggregations)
                subAggs.forEach { (name, subAgg) ->
                    agg.aggregations(name, subAgg)
                }
            }
        }
    }

    private fun parseRanges(rangesParam: Any?): List<AggregationRange> {
        // ranges: [{"from": 0, "to": 50}, {"from": 50, "to": 100}, {"from": 100}]
        val ranges = (rangesParam as? List<*>) ?: return emptyList()
        return ranges.filterIsInstance<Map<*, *>>().map { r ->
            AggregationRange.of { ar ->
                r["from"]?.toString()?.let { ar.from(it) }
                r["to"]?.toString()?.let { ar.to(it) }
                r["key"]?.toString()?.let { ar.key(it) }
            }
        }
    }

    private fun buildNamedFilters(filtersParam: Any?): Buckets<Query> {
        // filters: {"active": {"term": {"status": "active"}}, "inactive": ...}
        val filters = (filtersParam as? Map<*, *>) ?: return Buckets.of { it.keyed(emptyMap()) }
        val queryMap = filters.entries.associate { (key, value) ->
            key.toString() to Query.of { q ->
                q.withJson(StringReader(objectMapper.writeValueAsString(value)))
            }
        }
        return Buckets.of { it.keyed(queryMap) }
    }
}

enum class AggregationType {
    // Bucket
    TERMS, DATE_HISTOGRAM, HISTOGRAM, RANGE, FILTERS,
    // Metric
    AVG, SUM, MIN, MAX, VALUE_COUNT, CARDINALITY,
}

data class AggregationNode(
    val name: String,
    val type: AggregationType,
    val field: String,
    val params: Map<String, Any> = emptyMap(),
    val subAggregations: List<AggregationNode> = emptyList(),  // Tier 2
)
```

### 3-3. ES 9.x Aggregation API 매핑 (상세)

```kotlin
// 실제 ES 호출 (AggregationExecutor)
@Service
class AggregationExecutor(private val clientFactory: ElasticsearchClientFactory) {

    fun execute(
        clusterId: String,
        index: String,
        aggregations: Map<String, Aggregation>,
        query: Map<String, Any>? = null,
    ): SearchResponse<JsonData> {
        val esClient = clientFactory.getClient(clusterId)
        return esClient.search({ s ->
            s.index(index)
                .size(0)  // 집계만 필요
                .aggregations(aggregations)
                .also { builder ->
                    if (query != null) {
                        builder.query { q ->
                            q.withJson(StringReader(objectMapper.writeValueAsString(query)))
                        }
                    }
                }
        }, JsonData::class.java)
    }
}

// 응답 파싱 (AggregationResponseParser)
@Component
class AggregationResponseParser {

    fun parse(response: SearchResponse<JsonData>): Map<String, Any> {
        val result = mutableMapOf<String, Any>()
        response.aggregations().forEach { (name, agg) ->
            result[name] = parseAggregate(agg)
        }
        return result
    }

    private fun parseAggregate(agg: Aggregate): Any {
        return when {
            agg.isSterms() -> parseBuckets(agg.sterms().buckets().array()) { it.key().stringValue() to it.docCount() }
            agg.isLterms() -> parseBuckets(agg.lterms().buckets().array()) { it.key().toString() to it.docCount() }
            agg.isDateHistogram() -> parseBuckets(agg.dateHistogram().buckets().array()) { it.keyAsString() to it.docCount() }
            agg.isHistogram() -> parseBuckets(agg.histogram().buckets().array()) { it.key().toString() to it.docCount() }
            agg.isRange() -> parseBuckets(agg.range().buckets().array()) { (it.key() ?: "${it.from()}-${it.to()}") to it.docCount() }
            agg.isFilters() -> {
                agg.filters().buckets().keyed().mapValues { (_, bucket) -> bucket.docCount() }
            }
            agg.isAvg() -> mapOf("value" to agg.avg().value())
            agg.isSum() -> mapOf("value" to agg.sum().value())
            agg.isMin() -> mapOf("value" to agg.min().value())
            agg.isMax() -> mapOf("value" to agg.max().value())
            agg.isValueCount() -> mapOf("value" to agg.valueCount().value())
            agg.isCardinality() -> mapOf("value" to agg.cardinality().value())
            else -> mapOf("_type" to agg._kind().name)
        }
    }

    private fun <T> parseBuckets(buckets: List<T>, extractor: (T) -> Pair<String, Long>): List<Map<String, Any>> {
        return buckets.map { bucket ->
            val (key, count) = extractor(bucket)
            mapOf("key" to key, "doc_count" to count)
        }
    }
}
