```kotlin
@RestController
@RequestMapping("/api/v1/aggregation")
class AggregationController(
    private val dslBuilder: AggregationDslBuilder,
    private val executor: AggregationExecutor,
    private val responseParser: AggregationResponseParser,
    private val fieldService: AggregationFieldService,
    private val queryRepository: AggregationQueryRepository,
) {
    /** 빌더 JSON → ES Aggregation DSL 미리보기 */
    @PostMapping("/build")
    fun buildPreview(@RequestBody request: AggregationBuildRequest): Map<String, Any> {
        val aggregations = dslBuilder.build(request.aggregations)
        // Aggregation 객체를 JSON으로 직렬화하여 미리보기 반환
        return mapOf("aggs" to aggregations.mapValues { /* serialize */ })
    }

    /** 집계 실행 */
    @PostMapping("/execute")
    fun execute(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestBody request: AggregationBuildRequest,
    ): Map<String, Any> {
        val aggregations = dslBuilder.build(request.aggregations)
        val response = executor.execute(clusterId, request.index, aggregations, request.query)
        return responseParser.parse(response)
    }

    /** 인덱스의 집계 가능 필드 목록 */
    @GetMapping("/fields/{index}")
    fun getFields(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable index: String,
    ): List<AggregableField> = fieldService.getAggregableFields(clusterId, index)

    /** 집계 쿼리 템플릿 CRUD */
    @PostMapping("/templates")
    fun saveTemplate(
        @RequestHeader("cluster-id") clusterId: String,
        @RequestBody query: AggregationQuery,
    ): AggregationQuery = queryRepository.save(query.copy(clusterId = clusterId))

    @GetMapping("/templates")
    fun listTemplates(
        @RequestHeader("cluster-id") clusterId: String,
    ): List<AggregationQuery> = queryRepository.findAllByClusterId(clusterId)

    @GetMapping("/templates/{id}")
    fun getTemplate(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable id: String,
    ): AggregationQuery = queryRepository.findByClusterIdAndId(clusterId, id)
        ?: throw NotFoundException("집계 쿼리를 찾을 수 없습니다: $id")

    @DeleteMapping("/templates/{id}")
    fun deleteTemplate(
        @RequestHeader("cluster-id") clusterId: String,
        @PathVariable id: String,
    ) = queryRepository.deleteByClusterIdAndId(clusterId, id)
}

data class AggregationBuildRequest(
