        |인덱스: ${info.index}
        |오류: ${message ?: "알 수 없음"}
    """.trimMargin()

    fun indexingSuccess(info: IndexingInfo): String {
        val elapsed = ((info.endTime ?: System.currentTimeMillis()) - info.startTime) / 1000
        return """
            |[SUCCESS] 색인 완료
            |컬렉션: ${info.collection.name}
            |인덱스: ${info.index}
