### 3-3. ES 9.x Aggregation API 매핑 (상세)

```kotlin
// 실제 ES 호출 (AggregationExecutor)
@Service
class AggregationExecutor(private val clientFactory: ElasticsearchClientFactory) {

    fun execute(
        clusterId: String,
        index: String,
        aggregations: Map<String, Aggregation>,
        query: Map<String, Any>? = null,
    ): SearchResponse<JsonData> {
        val esClient = clientFactory.getClient(clusterId)
        return esClient.search({ s ->
            s.index(index)
                .size(0)  // 집계만 필요
                .aggregations(aggregations)
                .also { builder ->
                    if (query != null) {
                        builder.query { q ->
                            q.withJson(StringReader(objectMapper.writeValueAsString(query)))
                        }
                    }
                }
        }, JsonData::class.java)
    }
}

// 응답 파싱 (AggregationResponseParser)
@Component
class AggregationResponseParser {

    fun parse(response: SearchResponse<JsonData>): Map<String, Any> {
        val result = mutableMapOf<String, Any>()
        response.aggregations().forEach { (name, agg) ->
            result[name] = parseAggregate(agg)
        }
        return result
    }

    private fun parseAggregate(agg: Aggregate): Any {
        return when {
            agg.isSterms() -> parseBuckets(agg.sterms().buckets().array()) { it.key().stringValue() to it.docCount() }
            agg.isLterms() -> parseBuckets(agg.lterms().buckets().array()) { it.key().toString() to it.docCount() }
            agg.isDateHistogram() -> parseBuckets(agg.dateHistogram().buckets().array()) { it.keyAsString() to it.docCount() }
            agg.isHistogram() -> parseBuckets(agg.histogram().buckets().array()) { it.key().toString() to it.docCount() }
            agg.isRange() -> parseBuckets(agg.range().buckets().array()) { (it.key() ?: "${it.from()}-${it.to()}") to it.docCount() }
            agg.isFilters() -> {
                agg.filters().buckets().keyed().mapValues { (_, bucket) -> bucket.docCount() }
            }
            agg.isAvg() -> mapOf("value" to agg.avg().value())
            agg.isSum() -> mapOf("value" to agg.sum().value())
            agg.isMin() -> mapOf("value" to agg.min().value())
            agg.isMax() -> mapOf("value" to agg.max().value())
            agg.isValueCount() -> mapOf("value" to agg.valueCount().value())
            agg.isCardinality() -> mapOf("value" to agg.cardinality().value())
            else -> mapOf("_type" to agg._kind().name)
        }
    }

    private fun <T> parseBuckets(buckets: List<T>, extractor: (T) -> Pair<String, Long>): List<Map<String, Any>> {
        return buckets.map { bucket ->
            val (key, count) = extractor(bucket)
            mapOf("key" to key, "doc_count" to count)
        }
    }
}
